def read_json(rel_path: str) -> Any:
    return json.loads((PACKAGE_DIR / rel_path).read_text(encoding="utf-8-sig"))


def read_text(rel_path: str, encoding: str = "utf-8") -> str:
    return (PACKAGE_DIR / rel_path).read_text(encoding=encoding, errors="replace")


def strip_html(text: str) -> str:
    text = re.sub(r"<script\b.*?</script>", " ", text, flags=re.I | re.S)
    text = re.sub(r"<style\b.*?</style>", " ", text, flags=re.I | re.S)
    text = re.sub(r"<[^>]+>", " ", text)
    text = unescape(text)
    return re.sub(r"\s+", " ", text).strip()


def rolling_max(values: list[float], window: int) -> float:
    if len(values) < window:
        return sum(values)
    return max(sum(values[i : i + window]) for i in range(len(values) - window + 1))


def longest_positive_run(values: list[float]) -> int:
    best = 0
    current = 0
    for value in values:
        if value > 0:
            current += 1
            best = max(best, current)
        else:
            current = 0
    return best


def tolerance(target: float, absolute_tolerance: float) -> dict[str, float]:
    return {"target": target, "absolute_tolerance": absolute_tolerance}


def main() -> None:
