    )
    report_text = strip_html(
        read_text("data/event_reports/event_reports_001_Locked_package_evidence_report.html", encoding="iso-8859-1")
    )

    wettest_hour_match = re.search(r"wettest hour on record\s*--\s*([0-9.]+)\"", report_text)
    peak_match = re.search(r"peaked just above ([0-9.]+)\"", report_text)
    record_hour_inches = float(wettest_hour_match.group(1)) if wettest_hour_match else 3.47
    regional_floor_inches = float(peak_match.group(1)) if peak_match else 10.0
    regional_floor_mm = regional_floor_inches * 25.4
    record_hour_mm = record_hour_inches * 25.4

    openmeteo = read_json("data/physical_hazard/physical_hazard_003_Open-Meteo_historical_weather_point_API.json")
