    precip = [float(value or 0.0) for value in hourly["precipitation"]]
    winds = [float(value or 0.0) for value in hourly["wind_speed_10m"]]
    event_total_mm = sum(precip)
    wettest_6h_mm = rolling_max(precip, 6)
    concentration = wettest_6h_mm / event_total_mm
    wet_hours = sum(value > 0 for value in precip)
    longest_wet_run_hours = longest_positive_run(precip)
    max_wind_kmh = max(winds)

